globalThis.SPANISH_TRAINER_DATA = globalThis.SPANISH_TRAINER_DATA || {};
Object.assign(globalThis.SPANISH_TRAINER_DATA, {"grammar":{"forms":{"construction.acabar_de_infinitive":{"bookTerm":"acabar de + infinitief","evidence":"book","paragraphs":["In de hier bedoelde aspectuele betekenis geeft acabar de + infinitief aan dat iets net is gebeurd: \u201czojuist iets gedaan hebben\u201d. Acabar draagt de persoon en tijd."],"references":[414],"sourcePaths":["OEBPS/Text/chapter14.html#dol414"]},"construction.estar_gerund":{"bookTerm":"estar + gerundio","evidence":"book","paragraphs":["Deze combinatie stelt een activiteit voor als gaande: \u201cbezig zijn met\u201d of \u201caan het \u2026 zijn\u201d. Estar draagt de persoon en tijd; de gerundio blijft onveranderlijk.","Bij reflexieve werkwoorden kan het voornaamwoord v\u00f3\u00f3r de vervoegde vorm van estar of vast aan de gerundio staan. De plaatsing bepaalt welke woorden je samen schrijft."],"references":[201,383],"sourcePaths":["OEBPS/Text/chapter13.html#dol201","OEBPS/Text/chapter14.html#dol383"]},"construction.ir_a_infinitive":{"bookTerm":"ir a + infinitief","evidence":"book","paragraphs":["Deze combinatie kan een voornemen of verwachte gebeurtenis uitdrukken: \u201cgaan\u201d of \u201czullen\u201d. Ir wordt vervoegd; daarna volgen a en de infinitief.","Deze omschrijving en de futuro zijn niet in iedere situatie uitwisselbaar. Ir a is vaak natuurlijk bij een al genomen besluit of een ontwikkeling die zich al aankondigt."],"references":[284,286,288,414],"sourcePaths":["OEBPS/Text/chapter14.html#dol284","OEBPS/Text/chapter14.html#dol286","OEBPS/Text/chapter14.html#dol288","OEBPS/Text/chapter14.html#dol414"]},"imperative.affirmative":{"bookTerm":"imperativo: bevestigend","evidence":"book","paragraphs":["Gebruik deze vorm voor een opdracht, verzoek of aansporing. De aanspreekvorm bepaalt de vervoeging; t\u00fa, usted en vosotros zijn dus niet verwisselbaar.","Bij een bevestigende opdracht worden zwakke voornaamwoorden aan het werkwoord vastgeschreven. Daardoor kunnen een uitgang en de geschreven klemtoon veranderen. Let dus ook op de plaats van het voornaamwoord en op accenttekens."],"references":[193,204,322,323,324],"sourcePaths":["OEBPS/Text/chapter13.html#dol193","OEBPS/Text/chapter13.html#dol204","OEBPS/Text/chapter14.html#dol322","OEBPS/Text/chapter14.html#dol323","OEBPS/Text/chapter14.html#dol324"]},"imperative.negative":{"bookTerm":"imperativo: ontkennend","evidence":"book","paragraphs":["Een verbod of ontkennende aansporing gebruikt no met een vorm van de presente de subjuntivo. Zet dus niet zomaar no v\u00f3\u00f3r een bevestigende imperatief.","Zwakke voornaamwoorden staan v\u00f3\u00f3r het werkwoord, na no. In deze app hoort bij een negatieve imperatief de volledige opgeslagen woordgroep, inclusief no, in het antwoord."],"references":[193,204,323],"sourcePaths":["OEBPS/Text/chapter13.html#dol193","OEBPS/Text/chapter13.html#dol204","OEBPS/Text/chapter14.html#dol323"]},"indicative.conditional":{"bookTerm":"condicional","evidence":"book","paragraphs":["De condicional is de verleden toekomende tijd, vaak vertaald met \u201czou\u201d. Hij kan de toekomst vanuit een verleden moment beschrijven, of het gevolg van een denkbeeldige voorwaarde.","Ook een vermoeden over het verleden is mogelijk. Gebruik deze vorm niet automatisch voor ieder Nederlands \u201czou\u201d: bij onzekerheid over het heden gebruikt het Spaans vaak de futuro."],"references":[191,267,290,291,294,315],"sourcePaths":["OEBPS/Text/chapter13.html#dol191","OEBPS/Text/chapter14.html#dol267","OEBPS/Text/chapter14.html#dol290","OEBPS/Text/chapter14.html#dol291","OEBPS/Text/chapter14.html#dol294","OEBPS/Text/chapter14.html#dol315"]},"indicative.conditional_perfect":{"bookTerm":"condicional perfecto","evidence":"book","paragraphs":["Deze vorm bestaat uit de condicional van haber en een voltooid deelwoord. Hij past bijvoorbeeld bij wat onder een andere voorwaarde gebeurd zou zijn.","De Nederlandse hulpvorm is \u201czou hebben gedaan\u201d of, afhankelijk van het werkwoord, \u201czou zijn gegaan\u201d. In het Spaans blijft het hulpwerkwoord haber."],"references":[197,200,315],"sourcePaths":["OEBPS/Text/chapter13.html#dol197","OEBPS/Text/chapter13.html#dol200","OEBPS/Text/chapter14.html#dol315"]},"indicative.future":{"bookTerm":"futuro de indicativo","evidence":"book","paragraphs":["De futuro simple kan een voorspelling, verwachting of belofte uitdrukken. Bij een regelmatig werkwoord staat de uitgang achter de hele infinitief. In deze oefeningen gaat het om een toekomstige gebeurtenis.","Deze tijd kan ook een vermoeden over het heden uitdrukken. Niet iedere toekomstige gebeurtenis vraagt om een futuro: de presente en ir a + infinitief zijn andere mogelijkheden."],"references":[190,284,285,286,287,289,290],"sourcePaths":["OEBPS/Text/chapter13.html#dol190","OEBPS/Text/chapter14.html#dol284","OEBPS/Text/chapter14.html#dol285","OEBPS/Text/chapter14.html#dol286","OEBPS/Text/chapter14.html#dol287","OEBPS/Text/chapter14.html#dol289","OEBPS/Text/chapter14.html#dol290"]},"indicative.future_perfect":{"bookTerm":"futuro perfecto","evidence":"synthesis","paragraphs":["Met de futuro van haber en een voltooid deelwoord beschrijf je wat op een toekomstig moment voltooid zal zijn. De vorm kan ook een vermoeden uitdrukken over iets dat al gebeurd is.","De Nederlandse vorm \u201czal hebben gedaan\u201d helpt de opbouw te herkennen; de context bepaalt of het om toekomst of een vermoeden gaat."],"references":[197,200,291],"sourcePaths":["OEBPS/Text/chapter13.html#dol197","OEBPS/Text/chapter13.html#dol200","OEBPS/Text/chapter14.html#dol291"]},"indicative.imperfect":{"bookTerm":"pret\u00e9rito imperfecto","evidence":"book","paragraphs":["Gebruik de imperfecto voor de achtergrond bij een gebeurtenis in het verleden: een toestand, wat toen gaande was of wat iemand geregeld deed. Je beschrijft de situatie zonder begin of einde centraal te stellen.","Het onderscheid met de indefinido is dus niet \u201clang tegenover kort\u201d. Beide kunnen in het Nederlands als een onvoltooid verleden tijd worden vertaald."],"references":[188,273,274,275,276],"sourcePaths":["OEBPS/Text/chapter13.html#dol188","OEBPS/Text/chapter14.html#dol273","OEBPS/Text/chapter14.html#dol274","OEBPS/Text/chapter14.html#dol275","OEBPS/Text/chapter14.html#dol276"]},"indicative.pluperfect":{"bookTerm":"pluscuamperfecto","evidence":"book","paragraphs":["Deze tijd combineert de imperfecto van haber met een voltooid deelwoord. Je beschrijft wat al gebeurd was v\u00f3\u00f3r een ander moment in het verleden.","De Nederlandse voltooid verleden tijd (\u201chad gedaan\u201d) past meestal als vertaling. De keuze hangt wel af van de samenhang tussen de gebeurtenissen."],"references":[197,200,279],"sourcePaths":["OEBPS/Text/chapter13.html#dol197","OEBPS/Text/chapter13.html#dol200","OEBPS/Text/chapter14.html#dol279"]},"indicative.present":{"bookTerm":"presente de indicativo","evidence":"book","paragraphs":["Gebruik deze tijd voor wat nu gebeurt, een huidige toestand of een gewoonte. De Nederlandse onvoltooid tegenwoordige tijd is meestal een goede vergelijking.","De presente kan ook naar de nabije toekomst verwijzen. In deze oefeningen gaat het om de expliciet gevraagde vorm; een tijdwoord alleen bepaalt niet welke tijd mogelijk is."],"references":[187,269,270],"sourcePaths":["OEBPS/Text/chapter13.html#dol187","OEBPS/Text/chapter14.html#dol269","OEBPS/Text/chapter14.html#dol270"]},"indicative.present_perfect":{"bookTerm":"pret\u00e9rito perfecto","evidence":"book","paragraphs":["Deze tijd bestaat uit de presente van haber en een voltooid deelwoord. Je kijkt vanuit het heden terug op wat is gebeurd: bijvoorbeeld binnen vandaag of deze week, of omdat het resultaat nu relevant is.","Dit is het gebruik dat deze app voor Spaans uit Spanje oefent. In andere regio\u2019s staat hier vaak een indefinido. De Nederlandse voltooid tegenwoordige tijd is geen automatische regel voor de Spaanse tijdkeuze."],"references":[197,200,272,274,275],"sourcePaths":["OEBPS/Text/chapter13.html#dol197","OEBPS/Text/chapter13.html#dol200","OEBPS/Text/chapter14.html#dol272","OEBPS/Text/chapter14.html#dol274","OEBPS/Text/chapter14.html#dol275"]},"indicative.preterite":{"bookTerm":"pret\u00e9rito indefinido","evidence":"book","paragraphs":["Je presenteert een gebeurtenis in het verleden als een geheel, of vertelt wat er achtereenvolgens gebeurde. Buiten een verhaal past deze tijd vaak bij een afgesloten tijdvak, zoals gisteren of vorig jaar.","Het gaat niet om hoe kort of lang iets duurde. In het Nederlands kan de vertaling zowel \u201cdeed\u201d als \u201cheeft gedaan\u201d zijn. Pret\u00e9rito perfecto simple is een andere naam voor deze tijd."],"references":[189,272,273,274,275,278],"sourcePaths":["OEBPS/Text/chapter13.html#dol189","OEBPS/Text/chapter14.html#dol272","OEBPS/Text/chapter14.html#dol273","OEBPS/Text/chapter14.html#dol274","OEBPS/Text/chapter14.html#dol275","OEBPS/Text/chapter14.html#dol278"]},"indicative.preterite_anterior":{"bookTerm":"pret\u00e9rito anterior","evidence":"book","paragraphs":["Dit is een zeldzame, formele samengestelde verleden tijd: de indefinido van haber met een voltooid deelwoord. Hij beschrijft iets dat voltooid was direct v\u00f3\u00f3r een volgende gebeurtenis in het verleden.","Het boek bespreekt dat modern Spaans hier meestal een gewone indefinido gebruikt. Deze vorm staat daarom niet in de standaard-oefenset."],"references":[197,200,277],"sourcePaths":["OEBPS/Text/chapter13.html#dol197","OEBPS/Text/chapter13.html#dol200","OEBPS/Text/chapter14.html#dol277"]},"nonfinite.compound_gerund":{"bookTerm":"gerundio perfecto","evidence":"synthesis","paragraphs":["Habiendo met een voltooid deelwoord is de samengestelde gerundio. Daarmee kan een bijwoordelijke constructie een voorafgaande, voltooide gebeurtenis aanduiden.","Deze vorm is onveranderlijk en heeft geen persoonsuitgang. In de zin moet duidelijk zijn op wie de handeling betrekking heeft."],"references":[200,377,379],"sourcePaths":["OEBPS/Text/chapter13.html#dol200","OEBPS/Text/chapter14.html#dol377","OEBPS/Text/chapter14.html#dol379"]},"nonfinite.compound_infinitive":{"bookTerm":"infinitivo perfecto","evidence":"book","paragraphs":["Deze vorm bestaat uit haber met een voltooid deelwoord. Zo kan een infinitiefconstructie aangeven dat iets al gebeurd is.","De vorm heeft zelf geen persoon. Niet elk Nederlands \u201cte hebben gedaan\u201d vereist in het Spaans deze samengestelde infinitief; de context is bepalend."],"references":[200,279],"sourcePaths":["OEBPS/Text/chapter13.html#dol200","OEBPS/Text/chapter14.html#dol279"]},"nonfinite.gerund":{"bookTerm":"gerundio","evidence":"book","paragraphs":["De gerundio is een onveranderlijke werkwoordvorm, meestal op -ando of -iendo. Met estar kan hij een activiteit beschrijven die gaande is; hij kan ook een bijwoordelijke functie hebben.","Hij is niet zonder meer gelijk aan het Nederlandse tegenwoordig deelwoord of de Engelse gerund. Een reflexief voornaamwoord kan aan deze vorm worden vastgeschreven."],"references":[184,201,377,379],"sourcePaths":["OEBPS/Text/chapter13.html#dol184","OEBPS/Text/chapter13.html#dol201","OEBPS/Text/chapter14.html#dol377","OEBPS/Text/chapter14.html#dol379"]},"nonfinite.infinitive":{"bookTerm":"infinitivo","evidence":"book","paragraphs":["De infinitief is het hele werkwoord, zonder een persoonsuitgang voor ik, jij of hij. Spaanse infinitieven eindigen op -ar, -er of -ir; bij een reflexief werkwoord staat se erachter.","Een infinitief kan onder meer bij een ander werkwoord of na een voorzetsel staan. Deze oefenvorm heeft zelf geen persoonslot."],"references":[183,395],"sourcePaths":["OEBPS/Text/chapter13.html#dol183","OEBPS/Text/chapter14.html#dol395"]},"nonfinite.participle":{"bookTerm":"participio pasado","evidence":"book","paragraphs":["Het voltooid deelwoord staat onder meer na haber om samengestelde tijden te vormen. Met haber verandert het niet mee met persoon, geslacht of getal.","Bij bijvoeglijk gebruik kan het juist wel naar geslacht en getal veranderen. De losse vorm in deze app is de opgeslagen basisvorm, geen automatisch verbogen bijvoeglijk naamwoord."],"references":[186,200,388,390],"sourcePaths":["OEBPS/Text/chapter13.html#dol186","OEBPS/Text/chapter13.html#dol200","OEBPS/Text/chapter14.html#dol388","OEBPS/Text/chapter14.html#dol390"]},"subjunctive.future":{"bookTerm":"futuro de subjuntivo","evidence":"book","paragraphs":["Dit is de zeldzame toekomende tijd van de aanvoegende wijs. Het boek noemt vooral vaste uitdrukkingen en juridische teksten als overgebleven gebruiksgebieden.","In gewoon modern Spaans kan de presente de subjuntivo al naar de toekomst verwijzen. Deze historische vorm is daarom geen standaard-oefentijd."],"references":[194,266],"sourcePaths":["OEBPS/Text/chapter13.html#dol194","OEBPS/Text/chapter14.html#dol266"]},"subjunctive.future_perfect":{"bookTerm":null,"evidence":"synthesis","paragraphs":["Dit is de samengestelde vorm bij de zeldzame futuro de subjuntivo: de futuro de subjuntivo van haber met een voltooid deelwoord. Hij heeft betrekking op een voorafgaande, voltooide gebeurtenis.","Het boek geeft hiervoor geen afzonderlijke definitie. Deze toelichting combineert de algemene uitleg over samengestelde tijden met die over de futuro de subjuntivo; de vorm is niet actief in de standaard-oefenset."],"references":[194,200,266],"sourcePaths":["OEBPS/Text/chapter13.html#dol194","OEBPS/Text/chapter13.html#dol200","OEBPS/Text/chapter14.html#dol266"]},"subjunctive.imperfect":{"bookTerm":"imperfecto de subjuntivo","evidence":"book","paragraphs":["Dit is een verleden vorm van de aanvoegende wijs. Hij past onder meer bij bepaalde bijzinnen in een verleden verhaal en bij denkbeeldige voorwaarden.","De varianten op -ra en -se zijn in de meeste subjuntivo-contexten uitwisselbaar. Bij bijzonder gebruik, bijvoorbeeld als een -ra-vorm in geschreven taal de functie van een indicativo heeft, geldt die uitwisselbaarheid niet zonder meer."],"references":[194,266,267,280,295,315],"sourcePaths":["OEBPS/Text/chapter13.html#dol194","OEBPS/Text/chapter14.html#dol266","OEBPS/Text/chapter14.html#dol267","OEBPS/Text/chapter14.html#dol280","OEBPS/Text/chapter14.html#dol295","OEBPS/Text/chapter14.html#dol315"]},"subjunctive.pluperfect":{"bookTerm":"pluscuamperfecto de subjuntivo","evidence":"book","paragraphs":["Deze tijd gebruikt hubiera of hubiese met een voltooid deelwoord. Hij komt onder meer voor bij iets dat al gebeurd was en bij een onvervulde voorwaarde in het verleden.","De hubiera- en hubiese-reeks zijn in zulke subjuntivo-contexten doorgaans beide mogelijk. In het Nederlands past vaak \u201chad gedaan\u201d; bij een onvervulde voorwaarde is vooral het verband met de hoofdzin belangrijk."],"references":[197,200,266,315],"sourcePaths":["OEBPS/Text/chapter13.html#dol197","OEBPS/Text/chapter13.html#dol200","OEBPS/Text/chapter14.html#dol266","OEBPS/Text/chapter14.html#dol315"]},"subjunctive.present":{"bookTerm":"presente de subjuntivo","evidence":"book","paragraphs":["De presente de subjuntivo komt voor in bepaalde zinsconstructies, bijvoorbeeld na een wens of in een doelzin met para que. Hij kan daarbij naar het heden \u00e9n de toekomst verwijzen.","De aanvoegende wijs betekent niet simpelweg \u201conzekerheid\u201d. De zinsbouw en de bedoeling bepalen of je subjuntivo of indicativo nodig hebt."],"references":[192,266,295,304,317],"sourcePaths":["OEBPS/Text/chapter13.html#dol192","OEBPS/Text/chapter14.html#dol266","OEBPS/Text/chapter14.html#dol295","OEBPS/Text/chapter14.html#dol304","OEBPS/Text/chapter14.html#dol317"]},"subjunctive.present_perfect":{"bookTerm":"pret\u00e9rito perfecto de subjuntivo","evidence":"book","paragraphs":["De presente de subjuntivo van haber met een voltooid deelwoord vormt deze tijd. De zin vraagt om de aanvoegende wijs en kijkt terug op een voorafgaande, voltooide gebeurtenis.","De Nederlandse vertaling heeft vaak \u201cheeft gedaan\u201d. Het Nederlandse tijdlabel vertelt op zichzelf niet of het Spaans een subjuntivo vereist."],"references":[197,200,266,295],"sourcePaths":["OEBPS/Text/chapter13.html#dol197","OEBPS/Text/chapter13.html#dol200","OEBPS/Text/chapter14.html#dol266","OEBPS/Text/chapter14.html#dol295"]}},"source":{"author":"E. Slager","copyright":"2010 Uitgeverij Unieboek | Het Spectrum bv","file":"9789000331697.epub","isbn":"9789000331697","note":"Korte uitleg in eigen woorden, gebaseerd op het lokaal aangeleverde boek; geen letterlijke definities.","publisher":"Prisma","sha256":"538b6c77bbfcad649a397be0a9b1ce9b25892a1e9ce67af0e9e08f8246b56fd0","title":"Grammatica Spaans: De regels van het Spaans"}}});
